<div class="container py-5"><span class="eyebrow">Admin</span><h1>Categories</h1><div class="panel p-4 mt-4"><form class="row g-2" method="POST" action="<?php echo e(route('admin.categories.store')); ?>"><?php echo csrf_field(); ?><div class="col-md-9"><input class="form-control" name="name" placeholder="Category name" required></div><div class="col-md-3"><button class="btn btn-success w-100">Add Category</button></div></form></div><div class="panel p-4 mt-4"><?php $__empty_1 = true; $__currentLoopData = $categories; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $category): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><div class="order-row flex-wrap"><div class="flex-grow-1"><b><?php echo e($category->name); ?></b><small><?php echo e($category->slug); ?></small></div><span class="badge text-bg-light"><?php echo e($category->products_count); ?> products</span><form method="POST" action="<?php echo e(route('admin.categories.delete',$category)); ?>" onsubmit="return confirm('Delete this category? Only categories with no products can be removed.')"><?php echo csrf_field(); ?> <?php echo method_field('DELETE'); ?><button class="btn btn-sm btn-outline-danger rounded-pill" <?php echo e($category->products_count ? 'disabled':''); ?>>Delete</button></form></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><div class="empty-state">No categories.</div><?php endif; ?></div></div>
